example.code:
@Version                            // optimistic lock — blocks lost updates
private Long version;

// Cascade justification: Role lifecycle is independent of User; no cascade.
// FetchType.LAZY is the correct default for collections.
@ManyToMany(fetch = FetchType.LAZY)
@JoinTable(name = "user_roles",
    joinColumns = @JoinColumn(name = "user_id"),
    inverseJoinColumns = @JoinColumn(name = "role_id"))
private Set<Role> roles = new HashSet<>();

// Cascade justification: Order lifecycle is fully owned by User.
// orphanRemoval: true because an Order without a User is invalid business state.
@OneToMany(mappedBy = "user", cascade = CascadeType.ALL, orphanRemoval = true)
private Set<Order> orders = new HashSet<>();

@CreationTimestamp
@Column(name = "created_at", updatable = false)
private LocalDateTime createdAt;

@UpdateTimestamp
@Column(name = "updated_at")
private LocalDateTime updatedAt;

// JOIN FETCH — loads roles in one query inside the transaction; no N+1.
@Query("SELECT u FROM User u JOIN FETCH u.roles WHERE u.id = :id")
Optional<User> findByIdWithRoles(@Param("id") Long id);

// Named parameters only — never string concatenation.
@Query("""
    SELECT u FROM User u
    WHERE (:name IS NULL OR LOWER(u.name) LIKE LOWER(CONCAT('%', :name, '%')))
    AND (:isActive IS NULL OR u.isActive = :isActive)
    """)
Page<User> search(@Param("name") String name,
                  @Param("isActive") Boolean isActive,
                  Pageable pageable);

@Modifying(clearAutomatically = true, flushAutomatically = true)
@Query("UPDATE User u SET u.isActive = false WHERE u.lastLoginAt < :cutoff")
int deactivateInactiveUsers(@Param("cutoff") LocalDateTime cutoff);

@NoRepositoryBean
public interface OrderRepository {                       // what services see
    Optional<Order> findById(UUID id);
    Optional<Order> findByIdWithItems(UUID id);
    Page<OrderSummaryDto> findAllSummaries(Pageable pageable);
    Order save(Order order);
}

interface OrderRepositoryJpa extends OrderRepository, JpaRepository<Order, UUID> {
    @Override
    @EntityGraph(attributePaths = {"items"})
    Optional<Order> findByIdWithItems(UUID id);

    @Override
    @Query("SELECT new faion.infra.orders.OrderSummaryDto(o.id, o.customerName, o.total) FROM Order o")
    Page<OrderSummaryDto> findAllSummaries(Pageable pageable);
}

@Service
@Transactional(readOnly = true)          // reads are the default; writes opt in
public class OrderService {

    private final OrderRepository repository;

    public OrderResponse getById(UUID id) {
        Order order = repository.findByIdWithItems(id)
            .orElseThrow(() -> new OrderNotFoundException(id));   // never .get()
        return OrderResponse.from(order);                        // mapped inside the tx
    }

    public Page<OrderSummaryDto> list(Pageable pageable) {
        return repository.findAllSummaries(pageable);            // no entity hydrated
    }

    @Transactional
    public OrderResponse create(CreateOrderRequest req) {
        Order order = new Order(req.customerName());
        repository.save(order);
        return OrderResponse.from(order);
    }
}
